import { getAllProducts } from '@/lib/db';
import { revalidateTag } from 'next/cache';

// Cache the products data with a "products" cache tag
const cachedGetAllProducts = async () => {
  'use cache';
  'use cache tag: products';
  return getAllProducts();
};

// Server action to invalidate the products cache
async function invalidateProductsCache() {
  'use server';
  revalidateTag('products');
}

// Child component that fetches and displays products
async function ProductsList() {
  const products = await cachedGetAllProducts();

  return (
    <div>
      <h2>Products</h2>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} - ${product.price}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Page() {
  return (
    <div>
      <h1>Home</h1>
      <ProductsList />

      <form action={invalidateProductsCache}>
        <button type="submit">
          Refresh Products (Invalidate Cache)
        </button>
      </form>
    </div>
  );
}

